package fleetflow.engine.flow;
import java.util.*;
public final class Dinic { private Dinic(){} public static int maxFlow(int[][] capacity,int s,int t){int n=capacity.length;int[][] r=new int[n][n];for(int i=0;i<n;i++)r[i]=capacity[i].clone();int total=0;int[] level=new int[n],it=new int[n];while(bfs(r,s,t,level)){Arrays.fill(it,0);int f;while((f=dfs(r,s,t,Integer.MAX_VALUE,level,it))>0)total+=f;}return total;}private static boolean bfs(int[][]r,int s,int t,int[]l){Arrays.fill(l,-1);l[s]=0;Queue<Integer>q=new ArrayDeque<>();q.add(s);while(!q.isEmpty()){int u=q.remove();for(int v=0;v<r.length;v++)if(r[u][v]>0&&l[v]<0){l[v]=l[u]+1;q.add(v);}}return l[t]>=0;}private static int dfs(int[][]r,int u,int t,int f,int[]l,int[]it){if(u==t)return f;for(;it[u]<r.length;it[u]++){int v=it[u];if(r[u][v]>0&&l[v]==l[u]+1){int x=dfs(r,v,t,Math.min(f,r[u][v]),l,it);if(x>0){r[u][v]-=x;r[v][u]+=x;return x;}}}return 0;} }
